{
  "investigate": [],
  "hypotheses": [
    {
      "service": "payment-service",
      "kind": "bad_deploy",
      "mechanism": "The v1.1 deploy at t=506 ('refactor webhook error handling') changed the order status written on payment capture from 'confirmed' to 'paid'; the I1 invariant expects 'confirmed', so every payment captured after the deploy violates it even though orders are being updated correctly.",
      "supporting": ["E1", "E3", "E9", "E11"],
      "refuting": ["E10"],
      "explains": ["I1_payment_has_order"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "payment-service"}},
        {"action": "replay_payment_confirmations", "params": {}}
      ]
    }
  ],
  "summary": "Payment-service v1.1 changed the order status string from 'confirmed' to 'paid' on capture, breaking the I1 invariant for all payments processed after the t=506 deploy; rolling back and replaying confirmations will restore the correct status."
}
